package com.modernarmory.item;

import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import software.bernie.geckolib.animatable.GeoItem;
import software.bernie.geckolib.animation.AnimatableManager;
import software.bernie.geckolib.animation.AnimationController;
import software.bernie.geckolib.animation.PlayState;
import software.bernie.geckolib.animation.RawAnimation;

/**
 * Animation names every gun's animation file provides (generated by tools/modelgen):
 * "idle" (loop), "fire", "reload", "reload_empty". Fire/reload are triggered from the server so
 * every player sees them.
 */
public final class GunAnimations {
    public static final String CONTROLLER = "main";
    public static final String ACTIONS = "actions";
    public static final String FIRE = "fire";
    public static final String RELOAD = "reload";
    public static final String RELOAD_EMPTY = "reload_empty";

    private static final RawAnimation IDLE = RawAnimation.begin().thenLoop("idle");

    static void register(GunItem gun, AnimatableManager.ControllerRegistrar controllers) {
        controllers.add(new AnimationController<>(gun, CONTROLLER, 2, state -> state.setAndContinue(IDLE)));
        controllers.add(new AnimationController<>(gun, ACTIONS, 0, state -> PlayState.STOP)
                .triggerableAnim(FIRE, RawAnimation.begin().thenPlay(FIRE))
                .triggerableAnim(RELOAD, RawAnimation.begin().thenPlay(RELOAD))
                .triggerableAnim(RELOAD_EMPTY, RawAnimation.begin().thenPlay(RELOAD_EMPTY)));
    }

    public static void trigger(GunItem gun, Player player, ItemStack stack, String anim) {
        if (player.level() instanceof ServerLevel level) {
            gun.triggerAnim(player, GeoItem.getOrAssignId(stack, level), ACTIONS, anim);
        }
    }

    /**
     * Plays {@code anim} from its start even if it is still running (GeckoLib ignores a trigger
     * for the animation that is already playing), e.g. the per-shell "reload" of a tube magazine.
     */
    public static void restart(GunItem gun, Player player, ItemStack stack, String anim) {
        if (player.level() instanceof ServerLevel level) {
            long id = GeoItem.getOrAssignId(stack, level);
            gun.stopTriggeredAnim(player, id, ACTIONS, anim);
            gun.triggerAnim(player, id, ACTIONS, anim);
        }
    }

    private GunAnimations() {}
}
